#include "/home/yiming/projects/fastest-bf-lab/benchmarks/all-external/adapters.hpp"
#include <iostream>
#include <set>
#include <string>
int main() {
 int count=0; std::set<std::string> names;
#define COUNT(T,H) ++count; names.emplace(#T); static_assert(sizeof(T)>0 && sizeof(H)>0)
 BF_REGISTER_EXTERNAL_FILTERS(COUNT);
 const int combined=count;
 if (names.size()!=static_cast<size_t>(combined)) return 1;
 count=0;
 BF_REGISTER_ROCKSDB_FILTERS(COUNT);
 const int rocks=count;
 count=0;
 BF_REGISTER_NATIVE_LAYOUT_FILTERS(COUNT);
 if (rocks!=5 || count!=2 || combined<rocks+count) return 2;
 std::cout << "Combined header rows=" << combined << ", RocksDB rows=" << rocks << ", native layout rows=" << count << "\n";
}

